cd /work/packages/zod/src/v4 && sed -i 's/unrepresentable: "throw" | "any" | UnrepresentableHandler<schemas.\$ZodType>;/unrepresentable: "throw" | "any" | UnrepresentableHandler<schemas.$ZodTypes>;/' core/to-json-schema.ts && sed -i 's/(ctx.unrepresentable as UnrepresentableHandler)({/(ctx.unrepresentable as UnrepresentableHandler<any>)({/' core/to-json-schema.ts
sed -i 's/let action: ReturnType<UnrepresentableHandler> =/let action: ReturnType<UnrepresentableHandler<any>> =/' core/to-json-schema.ts
cat >> classic/tests/to-json-schema.test.ts <<'E'

describe("unrepresentable handler", () => {
  test("selective handling, path and message", () => {
    const calls: any[] = [];
    const schema = z.object({ when: z.date(), id: z.bigint(), l: z.literal([undefined, 1n]) });
    const handler = ({ zodSchema, path, message }: any) => {
      calls.push([path, message]);
      return zodSchema._zod.def.type === "date" ? { type: "string", format: "date-time" } : "throw";
    };
    expect(() => z.toJSONSchema(schema, { unrepresentable: handler })).toThrow("BigInt cannot be represented");
    expect(calls[0]).toEqual([["properties", "when"], "Date cannot be represented in JSON Schema"]);
    expect(z.toJSONSchema(z.object({ when: z.date() }), { unrepresentable: handler }).properties).toEqual({
      when: { type: "string", format: "date-time" },
    });
  });

  test("literal, catch, any, override", () => {
    expect(z.toJSONSchema(z.literal([undefined, 1n]), { unrepresentable: () => ({ type: "integer" }) })).toMatchObject({
      type: "integer",
    });
    expect(z.toJSONSchema(z.literal([undefined, 1n]), { unrepresentable: () => "any" })).toMatchObject({ const: 1 });
    const c = z.string().catch(() => {
      throw new Error("x");
    });
    expect(z.toJSONSchema(c, { unrepresentable: () => ({ default: "fallback" }) })).toMatchObject({
      type: "string",
      default: "fallback",
    });
    expect(() => z.toJSONSchema(z.date(), { override: (ctx) => void (ctx.jsonSchema.nullable = true) })).toThrow();
  });
});
